const CACHE_PREFIX='process-design:'+new URL('./',self.location.href).pathname+':';
const CACHE=CACHE_PREFIX+'v17-source';
const ASSETS=['/','/index.html','/steam/','/steam/index.html','/ammonia/','/ammonia/index.html','/co2/','/co2/index.html','/co2/app.js','/co2/calc.js','/co2/records.js','/raven/raven.tokens.css','/style.css','/fonts/source-sans-3-latin-400.woff2','/fonts/source-sans-3-latin-500.woff2','/fonts/source-sans-3-latin-600.woff2','/fonts/LICENSE-SourceSans3.md','/shell.js','/install.mjs','/updates.mjs','/dates.mjs','/feedback.mjs','/prefs.mjs','/recent.mjs','/home.js','/recent-view.mjs','/history/','/history/index.html','/history/app.js','/settings/','/settings/index.html','/settings/app.js','/app.js','/units.mjs','/history.mjs','/report.mjs','/engine/worker.mjs','/engine/thermo.mjs','/engine/coolprop.js','/engine/coolprop.wasm','/engine/LICENSE-CoolProp.txt','/ammonia/app.js','/ammonia/calc.js','/ammonia/data.js','/ammonia/history.js','/manifest.webmanifest','/icon.svg','/raven-logo.png','/icons/raven-192.png','/icons/raven-512.png','/icons/raven-maskable-512.png','/icons/raven-apple-touch-180.png'].map(path=>new URL('.'+path,self.location.href).pathname);
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(ASSETS.map(path=>new Request(new URL(path,self.location.origin),{cache:'reload'})));await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith(CACHE_PREFIX)&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data?.type==='PROCESSCALC_VERSION')event.source?.postMessage({type:'PROCESSCALC_VERSION',version:CACHE.slice(CACHE_PREFIX.length)});});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;if(!ASSETS.includes(url.pathname))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const cached=await cache.match(url.pathname);return cached||fetch(event.request);})());});
